import { test, expect } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'

test('probe regulatoryAccountNew detail layout', async ({ page }) => {
  await page.setViewportSize({ width: 1920, height: 953 })
  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find(
    (r) => r.filePath === 'supervision/account/regulatoryAccountNew/index' && !String(r.path).includes(':tableid')
  )
  console.log('ROUTE=' + (listRoute ? listRoute.path : 'NOT_FOUND'))
  if (!listRoute) return
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)

  const firstRow = page.locator('.el-table__body tbody tr').first()
  const rowCount = await firstRow.count()
  console.log('ROWS=' + rowCount)
  if (rowCount === 0) return
  await firstRow.locator('td').nth(2).click()
  await page.waitForURL(/formMode=view/, { timeout: 20000 }).catch(() => {})
  await waitForPageLoading(page)
  await page.locator('.detail-container').waitFor({ state: 'visible', timeout: 20000 })

  const info = await page.evaluate(() => {
    const c = document.querySelector('.detail-container')
    const appMain = document.querySelector('#app-main')
    const cs = getComputedStyle(c)
    return {
      headlines: [...c.querySelectorAll('.collapse-header--title')].map((h) => h.innerText.trim()),
      childClasses: [...c.children].map((el) => el.tagName.toLowerCase() + '.' + [...el.classList].join('.')),
      containerOverflowY: cs.overflowY,
      containerScrollH: c.scrollHeight,
      containerClientH: c.clientHeight,
      scrollable: c.scrollHeight > c.clientHeight + 4,
      appMainScrollH: appMain ? appMain.scrollHeight : null,
      appMainClientH: appMain ? appMain.clientHeight : null
    }
  })
  console.log('INFO=' + JSON.stringify(info, null, 1))
  await page.screenshot({ path: 'test-results/shot-regAcc-detail.png' })
})

