import { test } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'

test('probe overflow behaviour with injected extra content', async ({ page }) => {
  await page.setViewportSize({ width: 1920, height: 953 })
  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find(
    (r) => r.filePath === 'supervision/account/regulatoryAccountNew/index' && !String(r.path).includes(':tableid')
  )
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)
  await page.locator('.el-table__body tbody tr').first().locator('td').nth(2).click()
  await page.waitForURL(/formMode=view/, { timeout: 20000 }).catch(() => {})
  await waitForPageLoading(page)
  await page.locator('.detail-container').waitFor({ state: 'visible', timeout: 20000 })

  // 模拟“多一张 Headline 卡片”的场景：往 zs-form 里再插一张同结构卡片
  await page.evaluate(() => {
    const form = document.querySelector('.detail-container .zs-form')
    const lastCard = [...form.querySelectorAll('.collapse-container')].pop()
    const clone = lastCard.cloneNode(true)
    form.appendChild(clone)
  })

  const m = await page.evaluate(() => {
    const c = document.querySelector('.detail-container')
    const form = c.querySelector('.zs-form')
    const cards = [...form.querySelectorAll('.collapse-container')]
    const cRect = c.getBoundingClientRect()
    return {
      containerScrollH: c.scrollHeight,
      containerClientH: c.clientHeight,
      overflowY: getComputedStyle(c).overflowY,
      canScroll: c.scrollHeight > c.clientHeight + 4,
      containerBottom: Math.round(cRect.bottom),
      cards: cards.map((el) => ({
        title: el.querySelector('.collapse-header--title')?.innerText.trim(),
        bottom: Math.round(el.getBoundingClientRect().bottom),
        hiddenBelow: Math.round(el.getBoundingClientRect().bottom) > Math.round(cRect.bottom)
      }))
    }
  })
  console.log('OVERFLOW=' + JSON.stringify(m, null, 1))
  await page.screenshot({ path: 'test-results/shot-overflow-sim.png' })
})

