import { test, expect } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'

/**
 * 预售资金新详情页滚动回归：内容超出时能滚到底、不裁切；内容够时不出现滚动条。
 * 覆盖四个页面，逐页断言「最后一张卡片底部可到达」。
 */
const PAGES = [
  { file: 'supervision/account/regulatoryAccountNew/index', name: '监管账户' },
  { file: 'supervision/account/mainAccount/index', name: '监管主账户' },
  { file: 'supervision/account/regulatorOrg/index', name: '监管机构' },
  { file: 'supervision/account/superviseAgreementNew/index', name: '监管协议签署' }
]

for (const p of PAGES) {
  test(`${p.name}详情：内容溢出时可滚动到底，未溢出时不留滚动条`, async ({ page }) => {
    await page.setViewportSize({ width: 1920, height: 953 })
    await loginAsAdminOnce(page)
    const routes = await collectAppRoutes(page)
    const listRoute = routes.find((r) => r.filePath === p.file && !String(r.path).includes(':tableid'))
    expect(listRoute, `菜单未注册：${p.file}`).toBeTruthy()

    await gotoHashPath(page, listRoute.path)
    await waitForPageLoading(page)

    const firstRow = page.locator('.el-table__body tbody tr').first()
    await expect(firstRow, `${p.name} 列表无数据`).toBeVisible({ timeout: 20000 })
    await firstRow.locator('td').nth(2).click()
    await page.waitForURL(/formMode=view/, { timeout: 20000 })
    await waitForPageLoading(page)
    await expect(page.locator('.detail-container')).toBeVisible({ timeout: 20000 })
    await expect(page.locator('.detail-container .collapse-container').first()).toBeVisible({ timeout: 20000 })

    const result = await page.evaluate(() => {
      const container = document.querySelector('.detail-container')
      // 滚动承担者：溢出的那一层
      const formArea = container.querySelector('.detail-from-container')
      const candidates = [container, formArea].filter(Boolean)
      const scroller = candidates.find((el) => el.scrollHeight > el.clientHeight + 4)
      const lastCard = [...container.querySelectorAll('.collapse-container')].pop()
      const containerRect = container.getBoundingClientRect()
      const lastRect = lastCard ? lastCard.getBoundingClientRect() : null
      return {
        containerOverflowY: getComputedStyle(container).overflowY,
        containerCanScroll: container.scrollHeight > container.clientHeight + 4,
        formAreaOverflowY: formArea ? getComputedStyle(formArea).overflowY : null,
        formAreaCanScroll: formArea ? formArea.scrollHeight > formArea.clientHeight + 4 : null,
        hasScroller: Boolean(scroller),
        scrollerTag: scroller ? scroller.className : null,
        lastCardTitle: lastCard ? lastCard.querySelector('.collapse-header--title')?.innerText.trim() : null,
        lastCardFullyVisible: lastRect ? lastRect.bottom <= containerRect.bottom + 2 : null,
        containerBottom: Math.round(containerRect.bottom),
        lastCardBottom: lastRect ? Math.round(lastRect.bottom) : null
      }
    })

    console.log(`${p.name}=` + JSON.stringify(result, null, 1))

    if (result.hasScroller) {
      // 有内容溢出：必须能滚到底部，最后一张卡片完整可见
      await page.evaluate(() => {
        const container = document.querySelector('.detail-container')
        const formArea = container.querySelector('.detail-from-container')
        const scroller =
          [container, formArea].filter(Boolean).find((el) => el.scrollHeight > el.clientHeight + 4) || container
        scroller.scrollTop = scroller.scrollHeight
      })
      const afterScroll = await page.evaluate(() => {
        const container = document.querySelector('.detail-container')
        const lastCard = [...container.querySelectorAll('.collapse-container')].pop()
        return {
          lastCardBottom: Math.round(lastCard.getBoundingClientRect().bottom),
          containerBottom: Math.round(container.getBoundingClientRect().bottom)
        }
      })
      expect(
        afterScroll.lastCardBottom,
        `滚到底后最后一张卡片仍被裁切（bottom=${afterScroll.lastCardBottom} > 容器底 ${afterScroll.containerBottom}）`
      ).toBeLessThanOrEqual(afterScroll.containerBottom + 2)
    } else {
      // 内容未溢出：不裁切也不该有滚动条
      expect(result.lastCardFullyVisible, '最后一张卡片被裁切但页面无法滚动').toBe(true)
    }
  })
}

